from typing import Any
from typing import TextIO
import csv
import io
import os
REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254
EXCEL_EXTENSIONS = ('.xlsx', '.xlsm')


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def excel_to_csv_text(path: str, max_rows: int = MAX_ROWS) -> str:
    """Convert the first sheet of an Excel file to CSV text, keeping one CSV
    line per spreadsheet row so reported row numbers match Excel's row numbers."""
    from openpyxl import load_workbook  # requires: pip install openpyxl

    workbook = load_workbook(path, read_only=True, data_only=True)
    try:
        sheet = workbook.active
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator='\n')
        for index, cells in enumerate(sheet.iter_rows(values_only=True), 1):
            if index > max_rows + 1:  # header + capped data rows (+1 to trigger the cap error)
                break
            writer.writerow(
                '' if cell is None else str(cell).replace('\r', ' ').replace('\n', ' ')
                for cell in cells
            )
        return buffer.getvalue()
    finally:
        workbook.close()


def validate_users_upload(path: str, max_rows: int = MAX_ROWS) -> dict[str, Any]:
    """Validate an uploaded users export (.csv, .xlsx or .xlsm).

    Every row is checked; validation continues after errors so all problems are
    reported together. Returns:
        {"total_rows": int, "valid_count": int, "invalid_count": int,
         "invalid_rows": [{"row": <row number, header = 1>, "errors": [reasons]}]}
    """
    extension = os.path.splitext(path)[1].lower()
    try:
        if extension in EXCEL_EXTENSIONS:
            text = excel_to_csv_text(path, max_rows)
        elif extension == '.csv':
            with open(path, encoding='utf-8-sig', newline='') as handle:
                text = handle.read()
        else:
            return _report(0, [], [{'row': 1, 'errors': [f'unsupported file type: {extension or "none"}']}])
    except (OSError, UnicodeDecodeError) as exc:
        return _report(0, [], [{'row': 1, 'errors': [f'file could not be read: {type(exc).__name__}']}])
    except Exception as exc:  # corrupt or unreadable workbook
        return _report(0, [], [{'row': 1, 'errors': [f'spreadsheet could not be read: {type(exc).__name__}']}])

    valid, errors = import_users(text, max_rows)
    return _report(len(valid) + len(errors), valid, errors)


def _report(total_rows: int, valid: list[dict[str, Any]], errors: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        'total_rows': total_rows,
        'valid_count': len(valid),
        'invalid_count': len(errors),
        'invalid_rows': sorted(errors, key=lambda problem: problem['row']),
    }

